import json,hashlib
from pathlib import Path
from .setup import ROOT,PARENT,CAPTURE

def main():
 rows={f.stem.removeprefix('final_probe_'):json.loads(f.read_text())for f in sorted(ROOT.glob('final_probe_*.json'))}
 assert len(rows)==6 and all(len(v)==3 and all('error'not in x for x in v)for v in rows.values())
 validation=json.loads((ROOT/'validation.json').read_text());locked=json.loads((PARENT/'code_manifest.json').read_text())
 for f,h in locked.items():assert hashlib.sha256(Path(f).read_bytes()).hexdigest()==h,f
 studies={f.name:json.loads(f.read_text())for pattern in ['order_study_*.json','greedy_study_*.json','bitset_study_*.json','fast_study_*.json','fine_study_*.json']for f in ROOT.glob(pattern)}
 result=dict(status='implemented_not_adopted',baseline='Opt14 remains unchanged. Microbenchmark tensors are six recorded Opt11 Compact blocks from Opt13 captures, one Val trajectory, denoising step3.',source='https://svg-project.github.io/v2/',method='Query-only selection-based permutation; original per-query KV masks and original 32-query INT8 Q scales retained. Quantized Q and masks packed in permutation order; output scattered back by original index. K/V are not reordered.',final_probes=rows,studies=studies,validation=validation,parent_code_files_verified=len(locked),limitations=['Six real blocks from one trajectory, not all layers/steps/prompts.','CUDA-graph steady-state microbenchmarks include ordering, Q quantization, packing, union, K quantization/V packing, attention and output restoration; exclude compilation/capture.','No end-to-end video evaluation was run because every final candidate was slower on all six measured blocks.','These experiments do not reproduce full SVG2, which couples Q/KV feature clustering, permutation and sparse block selection.','Unchanged selections and quantization do not imply bitwise-identical outputs: split boundaries/online-softmax rounding change.'],conclusion='Permutation is valid and can reduce union size, but these lightweight candidates do not achieve net acceleration. Existing spatial order is already strong; global coarse hashes often worsen the union, while finer grouping costs more. This is not a proof that all reorderings will fail.')
 (ROOT/'report.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 lines=['Opt15：按选页集合重排 query 的实验','结论：已实现，当前候选未获得净加速，不接入默认推理路径。Opt14 未改动。','参考：SVG2 https://svg-project.github.io/v2/','', '流程：router生成逐query mask → 根据选页集合生成每个head的query排列 → 量化Q保留原32-query组scale → 按排列打包Q和mask并生成union → attention → 按原query索引写回。','只改变计算顺序；各query看到的KV完全保留。不使用投票、共享mask或Q64选择。','纯数学运算下逆排列后结果相同。实际kernel因split边界/在线softmax舍入而有微小差异。','', '最终两组轻量候选（位图压缩 + 局部新增page贪心分组）：','案例                      原版ms   64窗口重排ms  128窗口重排ms   原union   64窗口union']
 for case,rr in rows.items():
  d={x['method']:x for x in rr};a=d['BitsetFast_64_16_1'];b=d['BitsetFast_128_32_2'];original=d['Identity'];lines.append(f"{case:25s} {a['reference_ms']:.4f}    {a['full_ms']:.4f}       {b['full_ms']:.4f}       {original['union_fraction']:.2%}    {a['union_fraction']:.2%}")
 maxerr=max(x['nmse_vs_original']for rr in rows.values()for x in rr)
 lines+=['',f'最大输出NMSE：{maxerr:.3g}；Identity路径在6个block上与原内核逐位一致。',f"位图、尾query/page、全相同mask、稳定排列等独立验证：{validation['total']}例通过。",'所有最终排列都逐head检查为0..N-1的完整排列，包含4680 query的尾tile。','', '已比较的重排方法：','- 全局均值排序、MinHash、SimHash、按高熵page位排序。','- 16/32/64/128/256个固定mask锚点；32/128/256簇的轻量k-means。','- 64/128/256/512-query窗口内按Jaccard/cosine距离组成32-query tile。','- 将mask压成uint32位图，利用popcount直接最小化新增union page；减少排序轮次、减少warp数并跳过最后一组的多余选择。','- 索引式query加载与物理打包两种attention适配；后者开销更低，但仍没有净收益。','', '代表现象：','第14层，更重的分组能把union约35.6%降到30.6%，但排序成本约1.2ms；最轻版本排序约0.08ms，union仅降到33.7%。','第24层长历史，原union44.1%；轻量版43.1%，完整耗时约2.22→2.34ms。','更细128簇k-means可把第24层union降至约40.8%，但两轮聚类排序约1.4ms。','因此“union更小”不能直接当作加速；必须计入排列、数据搬运与量化scale保留成本。','', '边界：仅6个真实block、单trajectory、step3；没有全模型视频速度或质量结论。因微测全部退化，未启动端到端视频重跑。','这不是SVG2完整复现，也不能据此排除更高效的重排算法。SVG2同时设计Q/KV特征聚类与后续块级稀疏选择；当前实验是在已确定的逐query mask上做保留全部选择的重排。','', '关键代码：orders.py、bitset_fast.py、pack.py、attention_packed.py、final_probe.py、validate.py。','复现示例：CUDA_VISIBLE_DEVICES=0 streaming_sparse/.venv/bin/python -m migration.runtime.bootstrap migration.unified_router.opt15.final_probe --file layer24_chunk3.pt','全部原始数值：report.json / *_study_*.json / final_probe_*.json。']
 (ROOT/'report.txt').write_text('\n'.join(lines)+'\n')
 code={str(f.resolve()):hashlib.sha256(f.read_bytes()).hexdigest()for f in Path(__file__).parent.glob('*.py')};(ROOT/'code_manifest.json').write_text(json.dumps(code,indent=2)+'\n');(ROOT/'parent_lock.json').write_text(json.dumps(locked,indent=2)+'\n')
 (ROOT/'experiment.json').write_text(json.dumps(dict(status='completed_not_adopted',parent=str(PARENT),captures=str(CAPTURE),defaults_changed=False,source=result['source']),indent=2)+'\n')
 print('\n'.join(lines[:22]))
if __name__=='__main__':main()
